import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  index,
  jsonb,
  primaryKey,
  text,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import { bytea, tstz } from '../../../../platform/db/schema/columns.js';
import { authSchema } from '../../../../platform/db/schema/module-schemas.js';

/**
 * Tables of the auth module (architecture 5.2). `user`, `session`, `account` and `verification`
 * follow the Better Auth schema (property names are the Better Auth field names); the migration
 * is generated by drizzle-kit, Better Auth's own `getMigrations` is not used.
 */
export const user = authSchema.table(
  'user',
  {
    id: uuid('id').primaryKey(),
    name: text('name'),
    email: text('email'),
    emailVerified: boolean('email_verified').notNull().default(false),
    emailNormalized: text('email_normalized'),
    image: text('image'),
    githubUserId: bigint('github_user_id', { mode: 'number' }),
    githubLogin: text('github_login'),
    status: text('status').notNull().default('active'),
    isAdmin: boolean('is_admin').notNull().default(false),
    locale: text('locale').notNull().default('ru'),
    lastSeenAt: tstz('last_seen_at'),
    createdAt: tstz('created_at').notNull(),
    updatedAt: tstz('updated_at').notNull(),
  },
  (t) => [
    check('user_status_check', sql`${t.status} IN ('active','deleting','deleted')`),
    uniqueIndex('user_email_normalized_uq')
      .on(t.emailNormalized)
      .where(sql`${t.emailNormalized} IS NOT NULL`),
    uniqueIndex('user_github_user_id_uq')
      .on(t.githubUserId)
      .where(sql`${t.githubUserId} IS NOT NULL`),
  ],
);

/** Empty: sessions live in Redis only (`storeSessionInDatabase = false`); the table keeps the schema compatible. */
export const session = authSchema.table(
  'session',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    token: text('token').notNull(),
    expiresAt: tstz('expires_at').notNull(),
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    createdAt: tstz('created_at').notNull(),
    updatedAt: tstz('updated_at').notNull(),
  },
  (t) => [uniqueIndex('session_token_uq').on(t.token), index('session_user_idx').on(t.userId)],
);

/** OAuth tokens are encrypted by Better Auth (`encryptOAuthTokens`) and cleared after linking. */
export const account = authSchema.table(
  'account',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    providerId: text('provider_id').notNull(),
    accountId: text('account_id').notNull(),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    /** Never set (no passwords); Better Auth's schema check requires the column. */
    password: text('password'),
    accessTokenExpiresAt: tstz('access_token_expires_at'),
    refreshTokenExpiresAt: tstz('refresh_token_expires_at'),
    scope: text('scope'),
    createdAt: tstz('created_at').notNull(),
    updatedAt: tstz('updated_at').notNull(),
  },
  (t) => [
    uniqueIndex('account_provider_account_uq').on(t.providerId, t.accountId),
    index('account_user_idx').on(t.userId),
  ],
);

/** Magic link: `value` holds the hash of the token only (`storeToken: 'hashed'`, SEC-09). */
export const verification = authSchema.table(
  'verification',
  {
    id: uuid('id').primaryKey(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: tstz('expires_at').notNull(),
    createdAt: tstz('created_at').notNull(),
    updatedAt: tstz('updated_at').notNull(),
  },
  (t) => [index('verification_identifier_idx').on(t.identifier)],
);

export const consent = authSchema.table(
  'consent',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id),
    version: text('version').notNull(),
    textHash: bytea('text_hash').notNull(),
    acceptedAt: tstz('accepted_at').notNull(),
    ipHash: bytea('ip_hash'),
    revokedAt: tstz('revoked_at'),
  },
  (t) => [index('consent_user_idx').on(t.userId, t.acceptedAt.desc())],
);

export const deletionRequest = authSchema.table(
  'deletion_request',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id').notNull(),
    reason: text('reason').notNull(),
    status: text('status').notNull(),
    requestedAt: tstz('requested_at').notNull(),
    scheduledAt: tstz('scheduled_at').notNull(),
    cancelTokenHash: bytea('cancel_token_hash'),
    deadlineAt: tstz('deadline_at').notNull(),
    completedAt: tstz('completed_at'),
    cancelledAt: tstz('cancelled_at'),
  },
  (t) => [
    check('deletion_request_reason_check', sql`${t.reason} IN ('user_request','consent_revoked')`),
    check(
      'deletion_request_status_check',
      sql`${t.status} IN ('requested','in_progress','completed','cancelled')`,
    ),
    uniqueIndex('deletion_request_open_uq')
      .on(t.userId)
      .where(sql`${t.status} IN ('requested','in_progress')`),
    uniqueIndex('deletion_request_cancel_uq')
      .on(t.cancelTokenHash)
      .where(sql`${t.cancelTokenHash} IS NOT NULL`),
    index('deletion_request_scheduled_idx')
      .on(t.scheduledAt)
      .where(sql`${t.status} = 'requested'`),
  ],
);

export const deletionStep = authSchema.table(
  'deletion_step',
  {
    requestId: uuid('request_id')
      .notNull()
      .references(() => deletionRequest.id),
    module: text('module').notNull(),
    doneAt: tstz('done_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.requestId, t.module], name: 'deletion_step_pkey' })],
);

/** No personal data: counters only (FR-AUTH-09). */
export const deletionLog = authSchema.table('deletion_log', {
  id: uuid('id').primaryKey(),
  requestId: uuid('request_id')
    .notNull()
    .references(() => deletionRequest.id),
  module: text('module').notNull(),
  action: text('action').notNull(),
  counts: jsonb('counts').notNull(),
  at: tstz('at').notNull(),
});

/** Anti-fraud inputs (SEC-13): HMAC values only, never raw IPs or user agents. */
export const identitySignal = authSchema.table(
  'identity_signal',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    valueHmac: bytea('value_hmac').notNull(),
    firstSeen: tstz('first_seen').notNull(),
    lastSeen: tstz('last_seen').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.kind, t.valueHmac], name: 'identity_signal_pkey' }),
    check('identity_signal_kind_check', sql`${t.kind} IN ('ip24','ua','device')`),
    index('identity_signal_value_idx').on(t.kind, t.valueHmac, t.lastSeen),
  ],
);

/** Against bypassing anti-fraud by deleting the account (SEC-13); rows expire after 180 days. */
export const identityTombstone = authSchema.table(
  'identity_tombstone',
  {
    kind: text('kind').notNull(),
    valueHmac: bytea('value_hmac').notNull(),
    deletedAt: tstz('deleted_at').notNull(),
    expiresAt: tstz('expires_at').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.kind, t.valueHmac], name: 'identity_tombstone_pkey' }),
    check('identity_tombstone_kind_check', sql`${t.kind} IN ('github_user_id','email_normalized')`),
  ],
);
